import { Style, When } from '@pleat/core'
import { complexTokens } from './complex-tokens'
import { interactionTokens } from './interaction-tokens'
import { foundationTokens } from './foundations-tokens'
import { tokens } from './tokens'

/** Canonical roles shared by dialogs, menus, pickers, and transient feedback. */
export const overlayStyles = {
  arrow: Style.make({
    backgroundColor: tokens.primary,
    position: 'absolute',
    transform: 'rotate(45deg)',
    height: '0.625rem',
    width: '0.625rem',
  }),
  backdrop: Style.make({ inset: 0, position: 'fixed', zIndex: 40 }),
  close: Style.make({
    borderColor: tokens.transparent,
    borderRadius: complexTokens.smallRadius,
    borderStyle: 'solid',
    backgroundColor: tokens.transparent,
    boxShadow: tokens.shadowNone,
    cursor: interactionTokens.cursorAction,
    opacity: 0.7,
    outlineStyle: 'none',
    position: 'absolute',
    transitionDuration: interactionTokens.motionFast,
    transitionTimingFunction: interactionTokens.easingStandard,
    right: '1rem',
    top: '1rem',
  }).pipe(
    Style.when(When.focus, { boxShadow: tokens.focusRingOffsetShadow }),
    Style.when(When.hover, { opacity: 1 }),
    Style.when(When.reducedMotion, {
      transitionDuration: interactionTokens.motionNone,
    }),
  ),
  description: Style.make({
    color: tokens.mutedForeground,
    fontSize: '0.875rem',
    lineHeight: '1.25rem',
  }),
  dialog: Style.make({
    padding: 0,
    borderColor: tokens.transparent,
    alignItems: 'center',
    backgroundColor: tokens.transparent,
    display: 'none',
    justifyContent: 'center',
  }).pipe(Style.when(When.pseudo(':is([open])'), { display: 'flex' })),
  footer: Style.make({
    gap: '0.5rem',
    display: 'flex',
    flexDirection: 'column-reverse',
    justifyContent: 'flex-end',
  }).pipe(Style.when(When.minWidth('640px'), { flexDirection: 'row' })),
  group: Style.make({
    padding: '0.25rem',
    overflow: 'hidden',
    color: tokens.foreground,
  }),
  header: Style.make({
    gap: '0.5rem',
    display: 'flex',
    flexDirection: 'column',
    textAlign: 'center',
  }).pipe(Style.when(When.minWidth('640px'), { textAlign: 'left' })),
  icon: Style.make({
    color: tokens.mutedForeground,
    flexShrink: 0,
    pointerEvents: 'none',
    transitionDuration: interactionTokens.motionModerate,
    transitionTimingFunction: interactionTokens.easingStandard,
    height: '1rem',
    width: '1rem',
  }).pipe(
    Style.when(When.reducedMotion, {
      transitionDuration: interactionTokens.motionNone,
    }),
  ),
  indicator: Style.make({ display: 'flex', opacity: 0, marginLeft: 'auto' }),
  input: Style.make({
    borderColor: tokens.transparent,
    backgroundColor: tokens.transparent,
    color: tokens.foreground,
    fontFamily: 'inherit',
    fontSize: '0.875rem',
    lineHeight: '1.25rem',
    outlineStyle: 'none',
    height: '2.5rem',
    width: '100%',
  }),
  inputWrapper: Style.make({
    gap: '0.5rem',
    paddingInline: '0.75rem',
    alignItems: 'center',
    display: 'flex',
    borderBottomColor: tokens.border,
    borderBottomStyle: 'solid',
    borderBottomWidth: 1,
    height: '2.25rem',
  }),
  item: Style.make({
    borderRadius: tokens.controlRadius,
    gap: '0.5rem',
    paddingBlock: '0.375rem',
    paddingInline: '0.5rem',
    alignItems: 'center',
    backgroundColor: tokens.transparent,
    color: tokens.foreground,
    cursor: interactionTokens.cursorDefault,
    display: 'flex',
    fontSize: '0.875rem',
    lineHeight: '1.25rem',
    opacity: 1,
    outlineStyle: 'none',
    pointerEvents: 'auto',
    position: 'relative',
    userSelect: 'none',
    width: '100%',
  }).pipe(
    Style.when(
      When.pseudo(
        ':is([data-active="true"], [data-active=""], [data-selected])',
      ),
      { backgroundColor: tokens.accent, color: tokens.accentForeground },
    ),
    Style.when(When.hover, {
      backgroundColor: tokens.accent,
      color: tokens.accentForeground,
    }),
    Style.when(When.pseudo(':is([data-disabled], [aria-disabled="true"])'), {
      opacity: 0.5,
      pointerEvents: 'none',
    }),
  ),
  label: Style.make({
    paddingBlock: '0.375rem',
    paddingInline: '0.5rem',
    color: tokens.mutedForeground,
    fontSize: '0.75rem',
    lineHeight: '1rem',
  }),
  list: Style.make({
    padding: '0.25rem',
    maxHeight: '18.75rem',
    overflowX: 'hidden',
    overflowY: 'auto',
  }),
  media: Style.make({
    borderRadius: tokens.controlRadius,
    alignItems: 'center',
    backgroundColor: tokens.secondary,
    display: 'inline-flex',
    justifyContent: 'center',
    height: '4rem',
    width: '4rem',
  }),
  overlay: Style.make({
    inset: 0,
    backgroundColor: tokens.backdrop,
    opacity: 1,
    position: 'fixed',
    transitionDuration: interactionTokens.motionModerate,
    transitionProperty: 'opacity',
    transitionTimingFunction: interactionTokens.easingStandard,
    zIndex: 50,
  }).pipe(
    Style.when(When.data('closed'), { opacity: 0 }),
    Style.when(When.reducedMotion, {
      transitionDuration: interactionTokens.motionNone,
      transitionProperty: 'none',
    }),
  ),
  /* Menus, popovers, selects and comboboxes: shadcn `rounded-md bg-popover
     shadow-md`. Dialogs keep the larger panel radius. */
  /* Dialogs and sheets: shadcn `shadow-lg`. */
  modal: Style.make({
    boxShadow: foundationTokens.shadowLg,
  }),
  floating: Style.make({
    borderRadius: tokens.controlRadius,
    backgroundColor: foundationTokens.popover,
    boxShadow: foundationTokens.shadowMd,
  }),
  panel: Style.make({
    borderColor: tokens.border,
    borderRadius: tokens.radius,
    borderStyle: 'solid',
    borderWidth: 1,
    overflow: 'hidden',
    backgroundColor: tokens.background,
    boxShadow: tokens.shadowCard,
    color: tokens.foreground,
    opacity: 1,
    position: 'relative',
    transform: 'none',
    transitionDuration: interactionTokens.motionModerate,
    transitionProperty: 'opacity, transform',
    transitionTimingFunction: interactionTokens.easingStandard,
    zIndex: 50,
    maxWidth: 'calc(100vw - 2rem)',
    width: '100%',
  }).pipe(
    Style.when(When.data('closed'), { opacity: 0, transform: 'scale(0.95)' }),
    Style.when(When.reducedMotion, {
      transitionDuration: interactionTokens.motionNone,
      transitionProperty: 'none',
    }),
  ),
  panelContent: Style.make({ padding: '1rem' }),
  root: Style.make({
    borderRadius: tokens.controlRadius,
    overflow: 'hidden',
    backgroundColor: tokens.background,
    color: tokens.foreground,
    display: 'flex',
    flexDirection: 'column',
    width: '100%',
  }),
  separator: Style.make({
    marginBlock: '0.25rem',
    backgroundColor: tokens.border,
    pointerEvents: 'none',
    height: '1px',
  }),
  shortcut: Style.make({
    color: tokens.mutedForeground,
    fontSize: '0.75rem',
    letterSpacing: '0.1em',
    lineHeight: '1rem',
    marginLeft: 'auto',
  }),
  title: Style.make({
    color: tokens.foreground,
    fontSize: '1.125rem',
    fontWeight: 600,
    lineHeight: 1,
  }),
  tooltip: Style.make({
    borderRadius: tokens.controlRadius,
    paddingBlock: '0.375rem',
    paddingInline: '0.75rem',
    backgroundColor: tokens.primary,
    color: tokens.primaryForeground,
    fontSize: '0.75rem',
    lineHeight: '1rem',
    position: 'relative',
    textWrap: 'balance',
    zIndex: 50,
    width: 'fit-content',
  }),
  trigger: Style.make({
    borderColor: tokens.input,
    borderRadius: tokens.controlRadius,
    borderStyle: 'solid',
    borderWidth: 1,
    gap: '0.5rem',
    paddingBlock: '0.375rem',
    paddingInline: '0.625rem',
    alignItems: 'center',
    backgroundColor: tokens.transparent,
    boxShadow: tokens.shadowNone,
    color: tokens.foreground,
    cursor: interactionTokens.cursorAction,
    display: 'inline-flex',
    fontSize: '0.875rem',
    justifyContent: 'space-between',
    lineHeight: '1.25rem',
    opacity: 1,
    outlineStyle: 'none',
    pointerEvents: 'auto',
    minHeight: '2rem',
  }).pipe(
    Style.when(When.focusVisible, {
      borderColor: tokens.ring,
      boxShadow: tokens.focusRingShadow,
    }),
    Style.when(When.pseudo(':is([data-disabled], [aria-disabled="true"])'), {
      opacity: 0.5,
      pointerEvents: 'none',
    }),
  ),
  viewport: Style.make({ padding: '0.25rem', width: '100%' }),
}
